class Solution:
    def findPairs(self, x: int, cost: List[int]) -> int:
        c = Counter(v % x for v in cost)
        ans = 0
        for r, cnt in c.items():
            s = (x - r) % x
            if s == r:
                ans += cnt * (cnt - 1) // 2
            elif r < s:
                ans += cnt * c.get(s, 0)
        return ans

